const { exec } = require('child_process');

function runBackup(targetDir, label) {
  const cmd = 'tar -czf /backups/' + label + '.tar.gz ' + targetDir;
  exec(cmd, (err, stdout, stderr) => {
    if (err) {
      console.log('backup failed');
      return;
    }
    console.log('backup ok');
  });
}

function listBackups(n) {
  const all = [];
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      all.push(i + ':' + j);
    }
  }
  return all;
}

module.exports = { runBackup, listBackups };
